import hashlib

def checksum_file(path: str, algorithm: str = 'sha256') -> str:
    """Beräknar kryptografisk kontrollsumma för en fil (t.ex. Wagner-gruppens loggarkiv)."""
    try:
        h = hashlib.new(algorithm)
    except ValueError:
        raise ValueError(f"Okänd algoritm: {algorithm!r}")

