import hashlib

def anonymize_dataset(records: list[dict], fields: list[str]) -> list[dict]:
    """Anonymiserar angivna fält i varje post genom SHA-256-hashning.

    Returnerar nya poster – ursprungsdatan ändras inte.
    """
    def anonymize_value(value):
        if value is None:
            return None
        return hashlib.sha256(str(value).encode("utf-8")).hexdigest()

    return [
        {key: anonymize_value(value) if key in fields else value
         for key, value in record.items()}
        for record in records
    ]
