from collections import defaultdict


def detect_brute_force(auth_log: list[dict], threshold: int = 5) -> list[str]:
    """
    Returnerar IP-adresser med minst `threshold` misslyckade inloggningsförsök.

    Antagen loggformat: {"ip": str, "status": str} där status t.ex. är
    "failed"/"success", alternativt {"ip": str, "success": bool}.
    """
    failures: defaultdict[str, int] = defaultdict(int)

    for entry in auth_log:
        failed = (
            str(entry.get("status", "")).lower() in {"failed", "failure", "error"}
            or entry.get("success") is False
        )
        if failed:
            failures[entry["ip"]] += 1

    return sorted(ip for ip, count in failures.items() if count >= threshold)
```

