import os
import stat


def audit_file_permissions(directory: str) -> list[dict]:
    """Granskar filrättigheter i en katalog och returnerar filer/kataloger
    med för generösa behörigheter."""
    findings = []

    for root, dirs, files in os.walk(directory):
        for name in files + dirs:
            path = os.path.join(root, name)
            try:
                mode = os.lstat(path).st_mode
            except OSError:
                continue  # hoppa över oläsliga poster

            issues = []

            # World-writable fil
            if stat.S_ISREG(mode) and mode & stat.S_IWOTH:
                issues.append("world-writable fil")

            # World-writable katalog utan sticky bit (t.ex. /tmp-style skydd)
            if stat.S_ISDIR(mode) and mode & stat.S_IWOTH and not mode & stat.S_ISVTX:
                issues.append("world-writable katalog utan sticky bit")

            # Setuid/setgid kombinerat med world-writable
            if mode & (stat.S_ISUID | stat.S_ISGID) and mode & stat.S_IWOTH:
                issues.append("setuid/setgid + world-writable")

            # Körbar fil som är grupp-skrivbar
            if stat.S_ISREG(mode) and mode & stat.S_IXOTH and mode & stat.S_IWGRP:
                issues.append("körbar och grupp-skrivbar")

            if issues:
                findings.append({
                    "path": path,
                    "mode": oct(stat.S_IMODE(mode)),
                    "issues": issues,
                })

    return findings


if __name__ == "__main__":
    for f in audit_file_permissions("/tmp"):
        print(f"{f['mode']:>6}  {f['path']}  ->  {', '.join(f['issues'])}")
```

